// Vulnerable code: SQL Injection vulnerability
// This code directly concatenates user input into SQL query
public class UserDAO {
    public boolean authenticate(String username, String password) {
        String sql = "SELECT * FROM users WHERE username = '" + username + 
                     "' AND password = '" + password + "'";

        // Directly using user input in SQL query makes it vulnerable to injection
        try (Connection conn = DriverManager.getConnection(DB_URL);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            return rs.next(); // Returns true if user exists with given credentials
        } catch (SQLException e) {
            e.printStackTrace();
            return false;
        }
    }
}
```

***

```java
// Fixed code: Using PreparedStatement to prevent SQL Injection
// This code uses parameterized queries to safely handle user input
public class UserDAO {
    public boolean authenticate(String username, String password) {
        String sql = "SELECT * FROM users WHERE username = ? AND password = ?";

        // Using PreparedStatement with parameterized queries prevents SQL injection
        try (Connection conn = DriverManager.getConnection(DB_URL);
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

            pstmt.setString(1, username); // Safely set first parameter
            pstmt.setString(2, password); // Safely set second parameter

            try (ResultSet rs = pstmt.executeQuery()) {
                return rs.next(); // Returns true if user exists with given credentials
            }
        } catch (SQLException e) {
            e.printStackTrace();
            return false;
        }
    }
}
```

