**Fixed Code Snippet:**
```java
import java.io.*;
import java.nio.file.*;

public class FileServlet extends HttpServlet {
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        // This parameter is taken from user input
        String fileName = request.getParameter("file");

        // Validate file name: only allow alphanumeric characters, dots, and hyphens
        if (fileName == null || !fileName.matches("[a-zA-Z0-9.-]+")) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid file name");
            return;
        }

        // Define the base directory and resolve the file path safely
        Path baseDir = Paths.get("/var/www/uploads").toAbsolutePath();
        Path filePath = baseDir.resolve(fileName).normalize();

        // SECURE: Verify the resolved path is still within the base directory
        if (!filePath.startsWith(baseDir)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access denied");
            return;
        }

        // Check if file exists and is a regular file (not a directory)
        if (!Files.exists(filePath) || !Files.isRegularFile(filePath)) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found");
            return;
        }

        // Read and send file content securely using Files.copy
        Files.copy(filePath, response.getOutputStream());
    }
}
```

