// Good code example: Secure file path handling with validation
import java.io.*;
import java.nio.file.*;

public class SecureFileHandler {
    public static void main(String[] args) {
        String userInput = args[0]; // User-controlled input

        // SECURE: Validate and sanitize input before use
        // Normalize path to prevent directory traversal attacks
        Path basePath = Paths.get("/uploads").toAbsolutePath().normalize();
        Path userPath = Paths.get(userInput).normalize();
        Path resolvedPath = basePath.resolve(userPath).normalize();

        // Verify the resolved path is within the intended directory
        if (!resolvedPath.startsWith(basePath)) {
            System.out.println("Invalid file path: Attempted directory traversal");
            return;
        }

        // Additional security: Check file extension if applicable
        if (!resolvedPath.toString().endsWith(".txt")) {
            System.out.println("Only .txt files are allowed");
            return;
        }

        try {
            // Use try-with-resources for automatic resource management
            // This prevents resource leak vulnerabilities
            try (BufferedReader reader = Files.newBufferedReader(resolvedPath)) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(line);
                }
            }
        } catch (IOException e) {
            // Log error without exposing internal details to users
            System.err.println("Error accessing file");
        }
    }
